INSERT INTO tbl_room (rno, company, emp, ono)
SELECT SEQ_RNO.NEXTVAL, #{company}, #{emp}, #{ono}
FROM dual
WHERE NOT EXISTS (
    SELECT 1 FROM tbl_room
    WHERE company = #{company}
      AND emp = #{emp}
      AND ono = #{ono}
)

