	SELECT * FROM (
    SELECT r_regdate
    FROM tbl_userchat
    WHERE leader = #{leader}
      AND r_title = #{r_title}
      AND sch_date = #{sch_date}
    ORDER BY cno DESC
)
WHERE ROWNUM = 1

